def is_prime_ref(k: int) -> bool:
    if k < 2:
        return False
    if k % 2 == 0:
        return k == 2
    r = int(math.isqrt(k))
    for d in range(3, r + 1, 2):
        if k % d == 0:
            return False
    return True

def largest_prime_factor_ref(n: int) -> int:
    best = None
    d = 2
    m = n
    while d * d <= m:
        if m % d == 0:
            best = d
            while m % d == 0:
